$ cat Loaders.java
public class Loaders {
    static void show(String label, Class<?> c) {
        ClassLoader cl = c.getClassLoader();
        System.out.printf("  %-34s %s%n", label,
            cl == null ? "null  (bootstrap)"
                       : cl.getName() + "  (" + cl.getClass().getSimpleName() + ")");
    }
    public static void main(String[] a) {
        show("java.lang.String", String.class);
        show("java.util.ArrayList", java.util.ArrayList.class);
        show("javax.sql.DataSource", javax.sql.DataSource.class);
        show("java.sql.Driver", java.sql.Driver.class);
        show("Loaders (my own)", Loaders.class);
        for (ClassLoader c = Loaders.class.getClassLoader(); ; c = c.getParent()) {
            System.out.println("    " + (c == null ? "null  (bootstrap)" : c.getName()));
            if (c == null) break;
        }
    }
}

$ java -cp . Loaders

